//! Terminal rendering of the Narayanastra logo.
//!
//! Each `LOGO_*` table is the logo on a grid of sub-pixels, two across and two
//! down per terminal cell; digits index into `PALETTE` (0 = background). Each
//! cell is drawn with a Unicode quadrant block in up to two colours. The largest
//! size that fits the terminal is used.

use colored::*;

// Standard bright ANSI colours render the same in every terminal, unlike
// 24-bit colour which `colored` downgrades when COLORTERM is unset.
const PALETTE: [Color; 5] = [Color::Black, Color::BrightGreen, Color::BrightWhite, Color::BrightRed, Color::BrightYellow];

/// Quadrant glyphs indexed by mask: top-left 1, top-right 2, bottom-left 4, bottom-right 8.
const QUADRANTS: [char; 16] = [' ', '▘', '▝', '▀', '▖', '▌', '▞', '▛', '▗', '▚', '▐', '▜', '▄', '▙', '▟', '█'];

