/// Available sizes, largest first.
const SIZES: [&[&str]; 3] = [&LOGO_120, &LOGO_96, &LOGO_72];

fn most_common(values: impl Iterator<Item = u8>) -> Option<u8> {
    let mut counts = [0u8; 5];
    for v in values {
        counts[v as usize] += 1;
    }
    (1..5).filter(|&i| counts[i] > 0).max_by_key(|&i| counts[i]).map(|i| i as u8)
}

fn cell(q: [u8; 4]) -> ColoredString {
    let fg = match most_common(q.iter().copied().filter(|&v| v != 0)) {
        Some(c) => c,
        None => return " ".normal(),
    };
    let mask = q.iter().zip([1, 2, 4, 8]).filter(|(&v, _)| v == fg).map(|(_, b)| b).sum::<usize>();
    let glyph = QUADRANTS[mask].to_string().color(PALETTE[fg as usize]);
    let rest: Vec<u8> = q.iter().copied().filter(|&v| v != fg).collect();
    let blanks = rest.iter().filter(|&&v| v == 0).count();
    match most_common(rest.iter().copied().filter(|&v| v != 0)) {
        Some(bg) if rest.len() - blanks >= blanks => glyph.on_color(PALETTE[bg as usize]),
        _ => glyph,
    }
}

/// Terminal width in columns, if it can be determined.
fn terminal_width() -> Option<usize> {
    #[cfg(unix)]
    {
        let mut ws: libc::winsize = unsafe { std::mem::zeroed() };
        if unsafe { libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, &mut ws) } == 0 && ws.ws_col > 0 {
            return Some(ws.ws_col as usize);
        }
    }
    std::env::var("COLUMNS").ok().and_then(|c| c.trim().parse().ok())
}

/// The logo as terminal lines, sized to fit `margin` extra columns, and its width.
pub fn lines(margin: usize) -> (Vec<String>, usize) {
    let avail = terminal_width().unwrap_or(80).saturating_sub(margin);
    let pixels = SIZES.iter().find(|p| p[0].len() / 2 <= avail).unwrap_or(&SIZES[SIZES.len() - 1]);
    let width = pixels[0].len() / 2;
    let px = |r: usize, c: usize| pixels[r].as_bytes()[c] - b'0';
    let lines = (0..pixels.len() / 2)
        .map(|row| {
            (0..width)
                .map(|col| {
                    let (r, c) = (row * 2, col * 2);
                    cell([px(r, c), px(r, c + 1), px(r + 1, c), px(r + 1, c + 1)]).to_string()
                })
                .collect()
        })
        .collect();
    (lines, width)
}
